import sys


def factorize(n):
    factors = []
    m = abs(n)
    if m == 0:
        return "-1"
    if m == 1:
        return "1"
    if n < 0:
        factors.append("-1")
        m = -m
    d = 2
    while d * d <= m:
        count = 0
        while m % d == 0:
            count += 1
            m //= d
        if count:
            factors.append(f"{d}^{count}")
        d += 1
    if m > 1:
        factors.append(f"{m}")
    return " = ".join(factors)


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        n = int(line)
        print(f"{n} = {factorize(n)}")


if __name__ == "__main__":
    main()
